import { getNumericStyle } from "../getNumericStyle";
export const getBorders = (element) => {
    const styles = getComputedStyle(element);
    return {
        top: getNumericStyle(styles, "border-top-width"),
        bottom: getNumericStyle(styles, "border-bottom-width"),
        left: getNumericStyle(styles, "border-left-width"),
        right: getNumericStyle(styles, "border-right-width")
    };
};
